import data from './data.js';
import reconciliation from './reconciliation.js';
import {reconcileArtist} from '../../shared/reconcile.js';
import {reconciliationView} from './reconciled-view.js';
export const artist=reconcileArtist(data,reconciliation);
export function render({route,helpers:h}){
const e=h.escape,key=h.entityKey,url=(p,k=null,q=route.query)=>h.href(artist.slug,p,k,q);
const view=reconciliationView(artist,h,'wa');
const clearFilters=()=>{const q=new URLSearchParams(route.query);q.delete('q');q.delete('type');return url('works',null,q);};
const img=m=>m.image?h.image(m.image,m.nameZh+' '+m.name,{fit:'contain',position:'50% 50%'}):`<div class="wa-type-portrait">${e(m.name)}</div>`;
const member=(m,i=0)=>`<a class="wa-person" href="${url('member',key(m))}"><span class="wa-index">${String(i+1).padStart(2,'0')}</span><div class="wa-person-name"><h3>${e(m.nameZh)}</h3><p>${e(m.name)}</p>${m.historical?'<small>历史成员</small>':''}</div><div class="wa-person-photo">${img(m)}</div><span class="wa-arrow" aria-hidden="true">↗</span></a>`;
const record=w=>`<a class="wa-work ${w.type}" href="${url('work',key(w))}"><div class="wa-work-art">${w.image?h.image(w.image,w.title+' '+({release:'发行封面',mv:'MV预览',stage:'舞台预览'})[w.type],{fit:'contain'}):`<span>${w.type==='mv'?'MV':'LIVE'}</span>`}</div><div class="wa-work-type">${e(({release:'发行',mv:'MV',stage:'舞台'})[w.type])}</div><h3>${e(w.title)}</h3><p>${e(h.dateLabel(w.date,w.precision))}${w.version?' · '+e(w.version):''}</p></a>`;
const heading=(t,s='')=>`<div class="wa-heading"><h1>${e(t)}</h1>${s?`<p>${e(s)}</p>`:''}</div>`;
const nav=`<header class="wa-header"><a class="wa-brand" href="${url('home')}">WOOAH</a><nav aria-label="团体导航">${[['home','首页'],['members','成员'],['works','作品'],['timeline','时间轴']].map(([p,n])=>`<a href="${url(p)}" ${(route.page==='member'?'members':route.page==='work'?'works':route.page)===p?'aria-current="page"':''}>${n}</a>`).join('')}</nav></header>`;
let body='';
if(route.page==='home')body=`<section class="wa-opening"><div class="wa-opening-title"><h1>WOOAH</h1><p>让画面，<br>走出边框。</p><a class="wa-action" href="${url('works')}">浏览作品 ↗</a></div><figure class="wa-opening-image">${h.image(artist.hero,'WOOAH 官方五人时期团体照',{loading:'eager',fit:'contain',caption:true})}</figure></section><div class="wa-home-columns"><section class="wa-home-people"><div class="wa-section-heading"><h2>MEMBERS<span>成员</span></h2><a href="${url('members')}">全部 ↗</a></div><p class="wa-roster-note">${e(artist.historicalNote)}</p><div class="wa-people-list">${artist.members.map(member).join('')}</div></section><section class="wa-home-works"><div class="wa-section-heading"><h2>RECORDS<span>发行</span></h2><a href="${url('works')}">全部 ↗</a></div><div class="wa-record-wall">${artist.works.filter(w=>w.type==='release').slice(0,4).map(record).join('')}</div><a class="wa-timeline-door" href="${url('timeline')}"><strong>TIME<br>LINE</strong><span>从最早的作品开始 ↗</span></a></section></div>`;
else if(route.page==='members')body=heading('MEMBERS','成员目录 · '+artist.historicalNote)+`<div class="wa-directory">${artist.members.map(member).join('')}</div>`;
else if(route.page==='member'){
const m=artist.members.find(x=>key(x)===route.key);body=m?`<a class="wa-back" href="${url('members')}">← 返回成员目录</a><article class="wa-profile" data-member-id="${e(m.id)}"><div class="wa-profile-image">${img(m)}</div><div class="wa-profile-text"><p class="wa-roman">${e(m.name)}</p><h1>${e(m.nameZh)}</h1>${m.historical?'<p class="wa-status">历史成员</p>':''}<p>${e(view.profile(m))}</p>${view.career(m)}${view.sources(m.sources)}<a class="wa-action" href="${url('works')}">浏览团体作品 ↗</a></div></article>`:heading('没有找到这位成员')+`<a href="${url('members')}">返回成员目录</a>`;
}else if(route.page==='works'){
const q=route.query.get('q')||'',type=route.query.get('type')||'all',list=h.filterWorks(artist.works,{query:q,type});body=heading('WORKS','发行 / MV / 舞台')+`<form class="wa-search" data-work-search><label>搜索作品<input name="q" value="${e(q)}" placeholder="作品名称"></label><label>作品类型<select name="type">${[['all','全部'],['release','发行'],['mv','MV'],['stage','舞台']].map(([v,t])=>`<option value="${v}" ${type===v?'selected':''}>${t}</option>`).join('')}</select></label><button>查找 ↗</button></form><p class="wa-result" aria-live="polite">${list.length} 件作品</p><div class="wa-work-directory">${list.map(record).join('')}</div>${!list.length?`<div class="wa-empty"><h2>没有找到匹配作品。</h2><a href="${clearFilters()}">清除筛选 ↗</a></div>`:''}`;
}else if(route.page==='work'){
const w=artist.works.find(x=>key(x)===route.key);body=w?`<a class="wa-back" href="${url('works')}">← 返回作品目录</a><article class="wa-work-detail" data-work-key="${e(key(w))}"><div class="wa-detail-art">${w.image?h.image(w.image,w.title+' '+({release:'正式发行封面',mv:'MV预览',stage:'舞台预览'})[w.type],{fit:'contain',caption:true}):`<span>${w.type==='mv'?'MV':'LIVE'}</span>`}</div><div><p>${e(({release:'发行',mv:'MV',stage:'舞台'})[w.type])}</p>${heading(w.title)}<p class="wa-full-date">${e(h.dateLabel(w.date,w.precision))}</p><p>${e(w.dateKind||'')}</p>${w.version?`<p>${e(w.version)}</p>`:''}${h.sources(w.sources)}${w.videoId?`<a class="wa-action" href="${e(h.videoHref(w.videoId))}" target="_blank" rel="noopener">前往官方视频 ↗</a>`:''}</div></article>`:heading('没有找到这件作品')+`<a href="${url('works')}">返回作品目录</a>`;
}else if(route.page==='timeline')body=heading('TIMELINE','时间轴 · 从远到近')+`<ol class="wa-timeline">${h.sortTimeline(artist.timeline).map(t=>{const v=view.event(t);return `<li data-event-id="${e(v.id)}"><time${v.mainDate?` datetime="${e(v.mainDate)}"`:''}>${v.mainDate?e(h.dateLabel(v.mainDate,v.precision)):'历史事项'}</time><div><p class="wa-event-kind">${e(v.state)}</p><h2>${e(v.title)}</h2><p>${e(v.summary)}</p>${v.dates}${v.related.map(id=>`<a href="${url('work',id)}">关联作品 ↗</a>`).join('')}${v.sources}</div></li>`;}).join('')}</ol>`;
return`${nav}<main class="wa-main">${body}</main><footer class="wa-footer"><a class="wa-brand" href="${url('home')}">WOOAH</a><a href="${url('home')}">回到首页 ↑</a></footer>`;
}
export function afterRender({root,route,helpers:h}){const f=root.querySelector('[data-work-search]');if(!f)return;const cb=event=>{event.preventDefault();const d=new FormData(f),q=new URLSearchParams(route.query);const needle=String(d.get('q')||'');if(needle)q.set('q',needle);else q.delete('q');q.set('type',String(d.get('type')||'all'));location.hash=h.href(artist.slug,'works',null,q);};f.addEventListener('submit',cb);return()=>f.removeEventListener('submit',cb);}

// Presentation adapters only. Reconciled source fields and review decisions remain unchanged.
export function reconciliationView(artist,h,prefix){
 const e=h.escape;
 const heldURLs=new Set((artist.sourceTimeline||[]).filter(x=>x.reviewStatus!=='ready').flatMap(x=>(x.sources||[]).map(s=>s.url)));
 const stamp=d=>d?.value?h.dateLabel(d.value,d.precision):'';
 const sources=(rows=[],label='资料来源')=>{
  const list=rows.map(s=>typeof s==='string'?{url:s,title:'来源'}:s).filter(s=>/^https?:\/\//i.test(s?.url||'')&&!heldURLs.has(s.url));
  return list.length?`<details class="${prefix}-source-notes"><summary>${e(label)}</summary><ul>${list.map(s=>`<li><a href="${e(s.url)}" target="_blank" rel="noopener noreferrer">${e((s.title||s.label||'来源').replace(/^资料说明[：:]\s*/,''))}</a>${s.publisher?`<span>${e(s.publisher)}</span>`:''}${stamp(s.sourcePublishedAt)?`<p>原刊发布：<time datetime="${e(s.sourcePublishedAt.value)}">${e(stamp(s.sourcePublishedAt))}</time></p>`:''}</li>`).join('')}</ul></details>`:'';
 };
 const dateRow=(label,value,precision)=>value&&h.dateLabel(value,precision)?`<div><dt>${e(label)}</dt><dd><time datetime="${e(value)}">${e(h.dateLabel(value,precision))}</time></dd></div>`:'';
 const profile=m=>{
  // A legacy public profile contains a contract claim held by the mature event review.
  // Keep that original profile in artist/publicBaseline; do not adopt it as display copy.
  if(artist.slug==='rocketpunch'&&m.id==='recvxyICzHfdEb')return '官方资料中的兴趣包括涂色和摄影。';
  return m.displayProfile??m.profile??'';
 };
 const career=m=>{
  const periods=m.careerPeriods||[],rows=m.careerSources||[];
  return `<section class="${prefix}-career"><h2>成员资料与经历</h2>${m.role?`<p>${e(m.role)}</p>`:''}<p>${m.historical?'历史成员':'公开资料中的成员关系'}</p>${periods.map(p=>{
   const ps=rows.filter(s=>(p.sourceIds||[]).includes(s.sourceId||s.id));
   return `<article data-period-id="${e(p.periodId)}"><h3>${e(p.displayName||artist.name)}</h3><p>${p.relationType==='roster_listing'?'官方资料列示':'团体参与经历'}</p><dl>${dateRow(p.startDateBasis==='public_debut'?'团体公开出道':'资料记述起点',p.startDate,p.startPrecision)}${dateRow('资料记述结束',p.endDate,p.endPrecision)}${dateRow('相关公告',p.announcedDate?.value,p.announcedDate?.precision)}${dateRow('资料记述生效',p.effectiveDate?.value,p.effectiveDate?.precision)}</dl>${(p.events||[]).map(v=>`<p>${e(v.label||'')}${v.date?` <time datetime="${e(v.date)}">${e(h.dateLabel(v.date,v.precision))}</time>`:''}</p>`).join('')}${sources(ps,'经历来源')}</article>`;
  }).join('')}${sources(m.officialUrl?[{url:m.officialUrl,title:'个人资料原始来源'}]:[],'个人资料来源')}</section>`;
 };
 const event=t=>{
  const raw=t.canonicalEvent||t,states={announced:'公告',planned:'计划',postponed:'延期公告',cancelled:'取消公告'},types={debut:'出道',release:'发行',member_departure:'成员',contract_end:'合约',notice:'平台公告',other:'活动'};
  const main=raw.eventDate||raw.announcementDate;
  const dates=[['事项日期',raw.eventDate],['公告日期',raw.announcementDate],['计划日期',raw.plannedDate],['生效日期',raw.effectiveDate]].filter(([,d])=>stamp(d));
  const summary=(raw.publicSummary??raw.summary??'').replace(/同日专辑与主打合并为一次发行事件。?/g,'');
  const related=(raw.workIds||[]).filter(id=>artist.works.some(w=>w.id===id));
  return {id:raw.id,title:raw.title,summary,state:states[raw.status]||types[raw.eventType]||'事项',mainDate:main?.value||null,precision:main?.precision||null,dates:dates.length?`<dl class="${prefix}-event-dates">${dates.map(([label,d])=>dateRow(label,d.value,d.precision)).join('')}</dl>`:'',related,sources:sources(raw.sources||[],'事件来源')};
 };
 return {profile,career,event,sources};
}

