[data-artist="wooah"]{background:#090909;color:#f5f5f5;font:16px/1.7 Arial,"Noto Sans CJK SC",sans-serif;min-height:100vh}
[data-artist="wooah"] *{box-sizing:border-box;min-width:0}
[data-artist="wooah"] a{color:inherit;text-decoration:none}
[data-artist="wooah"] a:hover{color:#ff47b4}
[data-artist="wooah"] :is(a,button,input,select):focus-visible{outline:3px solid #ff47b4;outline-offset:5px}
[data-artist="wooah"] .wa-header{max-width:1540px;margin:auto;display:flex;justify-content:space-between;align-items:center;gap:30px;padding:24px 4%;border-bottom:1px solid #545454}
[data-artist="wooah"] .wa-brand{font-family:Impact,"Arial Narrow",sans-serif;font-size:34px;line-height:1;letter-spacing:-.04em}
[data-artist="wooah"] .wa-header nav{display:flex;gap:40px;font-weight:700;font-size:15px}
[data-artist="wooah"] [aria-current="page"]{color:#ff47b4;border-bottom:2px solid #ff47b4}
[data-artist="wooah"] .wa-main{max-width:1540px;margin:auto;padding:40px 4% 90px}
[data-artist="wooah"] .wa-opening{display:grid;grid-template-columns:.8fr 1.2fr;align-items:center;gap:2%;border-bottom:1px solid #545454;padding-bottom:48px;position:relative}
[data-artist="wooah"] .wa-opening-title h1{font-family:Impact,"Arial Narrow",sans-serif;font-size:clamp(80px,13vw,180px);letter-spacing:-.045em;font-weight:900;line-height:.9;margin:0 0 30px;word-break:break-all}
[data-artist="wooah"] .wa-opening-title>p{font-size:clamp(28px,3.2vw,46px);font-weight:800;line-height:1.4;margin:0 0 20px}
[data-artist="wooah"] .wa-opening-image{padding:12px;border:2px solid #ff47b4;transform:rotate(-1.5deg);margin:8px}
[data-artist="wooah"] figure{margin:0}
[data-artist="wooah"] img{max-width:100%;width:100%;height:auto;display:block}
[data-artist="wooah"] figcaption{font-size:11px;line-height:1.6;color:#c9c9c9;margin-top:10px;overflow-wrap:anywhere}
[data-artist="wooah"] .wa-action{display:inline-flex;align-items:center;min-height:48px;background:#ff47b4;color:#090909;padding:11px 22px;font-weight:800;margin:18px 0}
[data-artist="wooah"] .wa-action:hover{background:#f5f5f5;color:#090909}
[data-artist="wooah"] .wa-home-columns{display:grid;grid-template-columns:1.2fr 1fr;gap:5%;padding-top:48px}
[data-artist="wooah"] .wa-section-heading{display:flex;justify-content:space-between;align-items:baseline;gap:24px;padding-bottom:18px;border-bottom:1px solid #545454}
[data-artist="wooah"] .wa-section-heading h2{font:48px/.95 Impact,"Arial Narrow",sans-serif;letter-spacing:-.02em;margin:0}
[data-artist="wooah"] .wa-section-heading h2 span{font:14px/1.5 Arial,"Noto Sans CJK SC",sans-serif;display:inline-block;margin-left:15px}
[data-artist="wooah"] .wa-section-heading>a{font-size:13px;white-space:nowrap}
[data-artist="wooah"] .wa-roster-note{font-size:13px;color:#c9c9c9;margin:20px 0}
