  const naturalCap=capped?`;max-width:${details.width}px!important;max-height:${details.height}px!important;width:min(100%,${details.width}px)!important;height:auto!important;object-fit:contain!important;transform:none!important`:'';
  const img = `<img class="${className}" src="${escape(src)}" alt="${escape(alt)}" loading="${loading}" decoding="async"${dimensions} style="object-fit:${fit};object-position:${position}${naturalCap}" data-original-src="${escape(src)}"${capped?` data-no-upscale="true" data-quality-level="${escape(details.qualityLevel??'')}"`:''}>`;
